uint32_t fn_08(const uint8_t *in, size_t len, uint32_t arg, uint8_t *out, size_t out_cap)
{
    uint32_t h = 0xFFFFFFFF;
    size_t i;
    for (i = 0; i < len; i++) {
        h ^= in[i];
        uint8_t b;
        for (b = 0; b < 8; b++) {
            h = (h >> 1) ^ (-(h & 1) & 0xEDB88320);
        }
    }
    return ~h;
}
